package demo; import java.util.*; public class Probe { public static String probe(int o){if(o>=10){List<String>w=List.of("a","b","c","d").subList(1,3);try{switch(o){case 10:w.set(0,"x");break;case 11:w.add("y");break;case 12:w.remove(0);break;case 13:w.clear();break;}return String.valueOf(w);}catch(Exception e){return e.getClass().getName();}}List<String> p=new ArrayList<>(List.of("a","b","c","d"));List<String>v=p.subList(1,3);try{switch(o){case 0:v.set(0,"x");break;case 1:v.add("y");break;case 2:v.remove(0);break;case 3:v.clear();break;case 4:v.replaceAll(x->x.toUpperCase());break;case 5:v.sort(null);break;case 6:v.add("z");p.add("q");return v.get(0);case 7:Collections.sort(v);break;case 8:Collections.reverse(v);break;}return p+"|"+v;}catch(Exception e){return e.getClass().getName();}}public static String review(int o){List<String>p=new ArrayList<>(List.of("d","c","b","a"));List<String>v=p.subList(1,3);switch(o){case 4:v.replaceAll(x->x.toUpperCase());break;case 5:v.sort(null);break;case 7:Collections.sort(v);break;case 8:Collections.reverse(v);break;}return p+"|"+v+"|"+p.get(0)+"|"+v.get(0);}public static void main(String[]a){for(int i=0;i<4;i++)System.out.println(i+"="+probe(i));System.out.println("6="+probe(6));for(int i=10;i<14;i++)System.out.println(i+"="+probe(i));}}
